// Run only when vendored versions change. Release builds use the saved notices.
import { writeFile } from "node:fs/promises";

const sources = [
  ["Vue 2.7.16", "https://cdn.jsdelivr.net/npm/vue@2.7.16/LICENSE"],
  ["Vuetify 2.6.3", "https://cdn.jsdelivr.net/npm/vuetify@2.6.3/LICENSE.md"],
  ["Axios 0.26.1", "https://cdn.jsdelivr.net/npm/axios@0.26.1/LICENSE"],
  [
    "Roboto / @fontsource/roboto 5.3.0",
    "https://cdn.jsdelivr.net/npm/@fontsource/roboto@5.3.0/LICENSE",
  ],
  [
    "Material Design Icons 6.9.96 (font subset)",
    "https://cdn.jsdelivr.net/npm/@mdi/font@6.9.96/LICENSE",
  ],
  [
    "Apache License 2.0 (MDI font)",
    "https://www.apache.org/licenses/LICENSE-2.0.txt",
  ],
];
const notices = [
  "Third-party dependency notices\nMDI font is a subset generated by tools/vendor/build-mdi-subset.py.\n",
];
for (const [name, url] of sources) {
  const response = await fetch(url, { signal: AbortSignal.timeout(15000) });
  if (!response.ok) throw new Error(name + ": HTTP " + response.status);
  const text = await response.text();
  if (text.length < 300 || text.length > 30000)
    throw new Error("Unexpected license response for " + name);
  notices.push(
    "\n=== " +
      name +
      " ===\nSource: " +
      url +
      "\n\n" +
      text.replace(/\r\n/g, "\n") +
      "\n",
  );
}
await writeFile(
  new URL("../../cheat-engine/www/cheat/libs/LICENSES.txt", import.meta.url),
  notices.join(""),
);
console.log("Updated vendored license notices");
